"1009423": {"exam": "AI-103", "n": 66, "kind": "select", "area": "data/img/ai-103/image35.png", "blocks": [{"type": "code", "text": "import time\nfrom openai import OpenAI\nclient = OpenAI(\n    base_url= \"https://Contoso.openai.azure.com/openai/v1/\",\n    api_key=…,\n)\nvideo = client.videos.{{0}}(\n    model=deployment_name,\n        prompt= \"A video of our products\",\n    )\n    while video.status not in [\"completed\", \"failed\", \"cancelled\"]:\n        time.sleep(20)\n        video = client.videos.{{1}}(video.id)\n        print(video.status)", "slots": [{"options": ["create", "download_content", "list", "retrieve"], "answer": "create"}, {"options": ["create", "download_content", "list", "retrieve"], "answer": "retrieve"}]}], "note": "Indentation reproduced as shown in the image (one 0.5-inch step = 4 spaces); the original is irregular: prompt= sits one level deeper than model=, and the closing parenthesis and the while loop are indented one level under the create() call."},
"1009425": {"exam": "AI-103", "n": 68, "kind": "select", "area": "data/img/ai-103/image37.png", "blocks": [{"type": "code", "text": "from azure.identity import DefaultAzureCredential\nfrom azure.ai.projects import AIProjectClient\nfrom azure.core.credentials import AzureKeyCredential\nmyEndpoint = \"https://contoso.services.ai.azure.com/api/projects/project1\"\nproject_client = AIProjectClient(\n    endpoint=myEndpoint,\n    credential={{0}},\n)\nmyAgent = \"Agent1\"\nagent = project_client.agents.{{1}}(agent_name=myAgent)\nprint(f \"Retrieved agent: {agent.name}\")", "slots": [{"options": ["AzureKeyCredential()", "DefaultAzureCredential()", "None"], "answer": "DefaultAzureCredential()"}, {"options": ["create_version", "get", "get_version"], "answer": "get"}]}], "note": "The image shows a space between f and the opening quote in print(f \"Retrieved agent: {agent.name}\"); kept as shown."},
