"1009455": {"exam": "AI-103", "n": 98, "kind": "select", "area": "data/img/ai-103/image55.png", "blocks": [{"type": "code", "text": "resource existingKeyVault 'Microsoft.KeyVault/vaults@2024-11-01'\nexisting = {\n     name: 'KV1'\n     scope: resourceGroup()\n}\nresource connection\n'Microsoft.CognitiveSevices/accounts/connections@2025-04-01-\npreview' ={\n     name: '${aiFoundryName}-keyvault'\n     parent: aiFoundry\n     properties: {\n          category: {{0}}\n     target: existingKeyVault.id\n     authType: {{1}}\n     isSharedToAll:\n               metadata: {\n                    ApiType: 'Azure'\n                    ResourceId: existingKeyVault.id\n                    location: existingKeyVault.location\n               }\n          }\n     }", "slots": [{"options": ["'AzureAIService'", "'AzureKeyVault'", "'AzureOpenAI'"], "answer": "'AzureKeyVault'"}, {"options": ["'AccountKey'", "'AccountManagedIdentity'", "'ApiKey'"], "answer": "'AccountManagedIdentity'"}]}], "note": "The image misspells 'Microsoft.CognitiveSevices'; kept as shown, together with the image's line wraps (e.g. '2025-04-01-' / 'preview'') and its irregular indentation (tab stops written as 5 spaces)."},
