"1018512": {"exam": "AI-500", "n": 5, "kind": "yesno", "area": "data/img/ai-500/image6.png", "exhibits": {"data/img/ai-500/image5.png": [{"type": "code", "text": "project = AIProjectClient(\n    endpoint=os.environ[\"AZURE_AI_PROJECT_ENDPOINT\"],\n    credential=DefaultAzureCredential(),\n)\n\nopenai_client = project.get_openai_client()\nos.environ[\"AZURE_EXPERIMENTAL_ENABLE_GENAI_TRACING\"] = \"true\"\nconnection_string = project.telemetry.get_connection_string()\nconfigure_azure_monitor(connection_string=connection_string)\n\nAIProjectInstrumentor().instrument(\n    enable_content_recording=False,\n    enable_trace_context_propagation=True,\n)\n\n@trace_function()\ndef lookup_customer(email: str, loyalty_tier: str) -> str:\n    return f\"{email} ({loyalty_tier})\"\n\ndef main() -> None:\n    customer = lookup_customer(email=\"ada@example.com\", loyalty_tier=\"gold\")\n    response = openai_client.responses.create(\n        model=\"gpt-5.4\",\n        input=f\"Write a short thank-you note for customer {customer}.\",\n    )\n..."}]}, "head": ["Statements"], "blocks": [{"type": "row", "label": "responses.create() will record the prompt text and the model's generated response as a span attribute.", "answer": "No"}, {"type": "row", "label": "The stored OpenAI client will inject traceparent and tracestate headers into the responses.create() request.", "answer": "Yes"}, {"type": "row", "label": "The lookup_customer span will include code.function.parameter.email and code.function.parameter.loyalty_tier attributes.", "answer": "Yes"}]},
